def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    day = day_context['day']
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    serious_prev_bids = []
    desperate_signals = 0
    rich_opponents = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) >= DAILY_SALARY * 8:
                rich_opponents += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 2:
                desperate_signals += 1
            prev = opp.get('previous_trace', {})
            if prev:
                bid = prev.get('bid')
                status = prev.get('status')
                if bid is not None and status != 'error' and bid > 0:
                    serious_prev_bids.append(bid)

    if budget <= 0:
        return 0.0

    if not alive_opponents:
        if hp <= 3 or no_water_days >= 2:
            return float(min(budget, DAILY_SALARY * 0.75))
        return float(min(budget, DAILY_SALARY * 0.2))

    highest_prev = max(serious_prev_bids) if serious_prev_bids else 0.0
    avg_prev = (sum(serious_prev_bids) / len(serious_prev_bids)) if serious_prev_bids else 0.0

    tight_supply = supply <= 17
    medium_supply = supply <= 20
    abundant_supply = supply >= 23

    urgency = 0
    if hp <= 2:
        urgency += 4
    elif hp <= 4:
        urgency += 2
    if no_water_days >= 2:
        urgency += 4
    elif no_water_days >= 1:
        urgency += 2
    if tight_supply:
        urgency += 2
    elif medium_supply:
        urgency += 1
    if desperate_signals >= 2:
        urgency += 1

    base = DAILY_SALARY * 0.42

    if urgency >= 7:
        target = max(DAILY_SALARY * 1.02, highest_prev + 3.0, avg_prev + 6.0)
    elif urgency >= 5:
        target = max(DAILY_SALARY * 0.9, highest_prev + 2.0, avg_prev + 4.0)
    elif urgency >= 3:
        target = max(base + 10.0, highest_prev * 0.92 + 1.5)
    else:
        if abundant_supply:
            target = DAILY_SALARY * 0.28
        elif medium_supply:
            target = DAILY_SALARY * 0.4
        else:
            target = DAILY_SALARY * 0.52

    if highest_prev >= DAILY_SALARY * 1.6 and urgency <= 3:
        target = min(target, DAILY_SALARY * 0.38)

    if rich_opponents >= 2 and tight_supply:
        target += 6.0

    days_left = max(1, 10 - day + 1)
    sustainable = budget / days_left

    if urgency <= 2:
        cap = max(DAILY_SALARY * 0.35, sustainable * 0.9)
    elif urgency <= 4:
        cap = max(DAILY_SALARY * 0.6, sustainable * 1.15)
    else:
        cap = max(DAILY_SALARY * 0.95, sustainable * 1.8)

    if hp <= 2 or no_water_days >= 2:
        cap = max(cap, DAILY_SALARY * 1.1)

    bid = min(target, cap, budget)

    if bid < 0:
        bid = 0.0

    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = day_context.get('day', 0)

    # Alive opponents
    alive_opponents = []
    for opp in opponents_status.values():
        if opp.get('alive', False):
            alive_opponents.append(opp)

    # If no opponents alive, conserve budget
    if not alive_opponents:
        return max(0.0, min(my_status['budget'], DAILY_SALARY * 0.4))

    # Read yesterday bids from previous_trace for immediate reaction
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev.get('bid')))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Estimate how many water units are likely available per winner.
    # Use supply/water_req as a rough intensity proxy.
    supply_intensity = supply / float(WATER_REQ) if WATER_REQ else 0.0

    # Base bid: aim to secure enough water without burning budget.
    # If supply is high, we can bid less; if low, bid more.
    # Clamp into a sensible band around salary fractions.
    if supply_intensity >= 2.0:
        base = DAILY_SALARY * 0.45
    elif supply_intensity >= 1.4:
        base = DAILY_SALARY * 0.60
    else:
        base = DAILY_SALARY * 0.75

    # Escalate if yesterday showed very high pressure bids.
    # If someone was bidding close to salary, competition is intense.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        if my_status['hp'] > 3:
            base = max(base, DAILY_SALARY * 0.65)
        else:
            base = max(base, DAILY_SALARY * 0.95)

    # If my hp is critical, bid more aggressively.
    if my_status['hp'] <= 2:
        base = max(base, DAILY_SALARY * 0.95)
    elif my_status['hp'] <= 4:
        base = max(base, DAILY_SALARY * 0.75)

    # If I've already had no-water days, increase urgency.
    no_water_days = int(my_status.get('no_water_days', 0) or 0)
    if no_water_days >= 2:
        base = max(base, DAILY_SALARY * 0.85)

    # Convert to final bid within budget.
    budget = float(my_status.get('budget', 0.0))
    bid = min(budget, base)

    # Ensure non-negative
    if bid < 0.0:
        bid = 0.0

    return bid

